Method.Implementation:
$$$TRACE("Inside Method ProcessClaimRequest: " _ pRequest) Set pTarget = ##class(EnsLib.HTTP.GenericMessage).%New() Set tStream = ##class(%Stream.GlobalBinary).%New()
try {
set stat = pRequest.%JSONExportToStream(tStream) $$$TRACE("Data Export " _ stat)
Do pTarget.HTTPHeaders.SetAt("application/json","content-type")
Set pTarget.Stream = ##class(%Stream.GlobalBinary).%New() Set tStatus = pTarget.Stream.CopyFrom(tStream) $$$ThrowOnError(tStatus)
// Trace some data Do tStream.Rewind() Set tStr = tStream.Read() $$$TRACE("Data string size " _ tStream.Size _", Data: " _ tStr)
Do pTarget.HTTPHeaders.SetAt(tStream.Size,"content-length")
#dim tHttpResponse As EnsLib.HTTP.GenericMessage = ##class(EnsLib.HTTP.GenericMessage).%New()
Set tSC= ..OnMessage(pTarget, .tHttpResponse)
$$$TRACE("OnMessage, ISOK: " _ $$$ISOK(tSC) _", " _ tHttpResponse _", " _ $IsObject(tHttpResponse))
if ($IsObject(tHttpResponse.Stream)) { $$$TRACE(" Stream: " _ tHttpResponse.Stream.Size) }
If ( ($$$ISOK(tSC)) && ($IsObject(tHttpResponse)) && (tHttpResponse.Stream.Size > 0) ) {
set jSONstring = tHttpResponse.Stream.Read() $$$TRACE("Response size: " _ tHttpResponse.Stream.Size _", JSON: " _ jSONstring)
set pResponse = ##class(IHC.ITF.ITFCOMMON.Response.ClaimRestResponse).%New() set dynamicArray = ##class(%DynamicAbstractObject).%FromJSON(jSONstring) set pResponse.GetClaimDetailsResult = ##class(%ListOfObjects).%New()
set iter = dynamicArray.%GetIterator() while iter.%GetNext(.key, .value, .type ) { set newObj = value.%ToJSON() set stat = pResponse.GetClaimDetailsResult.Insert(newObj) $$$TRACE( stat _ " DynArray = "_key_ ", size = " _ $L(newObj) ) } $$$TRACE( "GetClaimDetailsResult Size: " _ pResponse.GetClaimDetailsResult.Count() ) }
} catch exp{ $$$LOGERROR("Exception: " _ exp) IF 1=exp.%IsA("%Exception.SystemException") { $$$TRACE( "System exception, Name: " _ $ZCVT(exp.Name,"O","HTML")) $$$TRACE( "Location: " _ exp.Location) $$$TRACE( "Code: " _ exp.Code) $$$TRACE( "Data: " _ exp.Data) set tSC = $$$ERROR("Exception in calling the service") } } return tSC
